function recolectarCitas(r) {
  const citas = [];
  const lista = (arr, ruta, emisor) => {
    if (Array.isArray(arr)) arr.forEach((n, i) => citas.push({ ruta: `${ruta}[${i}]`, n, emisorRequerido: emisor }));
