return module.exports;
})({ exports: {} });
// ===== FIN js/registro_errores.js =====
const { TIPOS_ERROR, WORKFLOWS, COLUMNAS_LOG_ERRORES, generarIdConConsecutivo, generarIdError, limpiarTexto, limpiarDetalle, detalleComoJson, debeAlertar, filaLogErrores, workflowDesdeNombre, tipoErrorDesdeNodo, analizarErrorTrigger } = __fuente_registro_errores;

