// Valores permitidos (glosario, sección 4). Son del contrato, no de la configuración editable.
const TIPOS_ERROR = [
  'payload_invalido',
  'tipo_interaccion_sin_rubrica',
  'evaluacion_sin_secciones_aplicables',
  'respuesta_llm_invalida',
  'fallo_nodo',
  'fallo_api',
  'fallo_sheets',
  'fallo_telegram',
  'generacion_invalida',
  'formulario_invalido',
];
