const TIPOS_INTERACCION = ['ce', 'sales'];

// Columnas de `log_errores`, en el orden de sheets.md.
const COLUMNAS_LOG_ERRORES = [
  'id_error',
  'ocurrido_en',
  'workflow',
  'nodo',
  'tipo_error',
  'mensaje_error',
  'conversation_id',
  'lote',
