const PATRONES_LIMPIEZA = [
  // Token de bot de Telegram: 6+ dígitos, dos puntos y una cadena larga.
  [/\b\d{6,}:[A-Za-z0-9_-]{30,}\b/g, '[REDACTADO]'],
