/**
 * Fila de `log_errores` (11 columnas exactas).
 *
 * datos: { workflow, nodo, tipo_error, mensaje_error, conversation_id, lote, tipo_interaccion,
 *          detalle, alerta_enviada, consecutivo }
 *
