 * const config = $('Config cargada').first().json;
 * return { json: filaLogErrores({ ...datos, alerta_enviada: true, consecutivo: $itemIndex + 1 }, config, new Date()) };
 * ------------------------------------------------------------------------- */
return module.exports;
})({ exports: {} });
// ===== FIN js/registro_errores.js =====
const { TIPOS_ERROR, WORKFLOWS, COLUMNAS_LOG_ERRORES, marcaTiempoSistema, generarIdConConsecutivo, generarIdError, limpiarTexto, limpiarDetalle, detalleComoJson, debeAlertar, filaLogErrores, workflowDesdeNombre, tipoErrorDesdeNodo, analizarErrorTrigger } = __fuente_registro_errores;

